typeDefs:
struct sftpjob {
  /** @brief Length of request */
  size_t len;

  /** @brief Complete bytes of request */
  unsigned char *data;

  /** @brief Bytes remaining to parse */
  size_t left;

  /** @brief Next byte to parse */
  const unsigned char *ptr;

  /** @brief Allocator to use */
  struct allocator *a;

  /** @brief Request ID or 0 */
  uint32_t id;

  /** @brief Worker processing this job */
  struct worker *worker; /* worker processing this job */
}

struct handleid {
  /** @brief Handle ID
   *
   * This is an index into the @ref handles array.  At any given moment no two
   * valid handles have the same ID, but handles that do not overlap in
   * lifetime will often have matching IDs.
   */
  uint32_t id;

  /** @brief Handle tag
   *
   * This is a sequence number, used to distinguish handles with the same ID.
   */
  uint32_t tag;
}

vulnerableMethods_after:
uint32_t sftp_parse_handle(struct sftpjob *job, struct handleid *id) { /* <=== sftp_parse_handle */ 
  uint32_t len, rc;

  if((rc = sftp_parse_uint32(job, &len)) != SSH_FX_OK)
    return rc;
  if(len != 8)
    return SSH_FX_BAD_MESSAGE;
  if((rc = sftp_parse_uint32(job, &id->id)) != SSH_FX_OK ||
     (rc = sftp_parse_uint32(job, &id->tag) != SSH_FX_OK))
    return rc;
  return SSH_FX_OK;
}

